register(globalThis.makeMedvezhonokEdition(2024, "1", [{"author":"А. Ковалёва","question":"Какой кличкой обычно не называют щенка?","choices":["Дружок","Шарик","Мурлыка","Бобик","Рекс"],"key":"В","review":["Клички щенка","«Дружок», «Шарик», «Бобик» и «Рекс» часто служат кличками собак.","Кличка «Мурлыка» связана со словом «мурлыкать». Так обычно называют кота или кошку."],"points":1},{"author":"А. Ковалёва","question":"Кто самый высокий?","choices":["Илья Муромец","Мальчик-с-пальчик","Дюймовочка","Мужичок с ноготок","Муха-Цокотуха"],"key":"А","review":["Рост героев","Имена Мальчика-с-пальчик, Дюймовочки и Мужичка с ноготок указывают на очень маленький рост. Муха-Цокотуха тоже невелика.","Из всех этих героев только Илья Муромец — взрослый богатырь. Он самый высокий."],"points":1},{"author":"А. Ковалёва","question":"Если поменять местами слоги в каждом слове, в одном случае получим название маленького грызуна. В каком?","choices":["насос","навес","камыш","лыжи","нора"],"key":"В","review":["Перестановка слогов","Разделим «камыш» на два слога: «ка-мыш». Поменяем их местами.","Получается «мыш-ка». Мышка — маленький грызун. Другие слова после такой перестановки грызуна не называют."],"points":1},{"author":"Е. Муравенко","question":"Как передвигаются эти животные? Черепаха _____, ласточка _____, дельфин _____, лиса _____.","choices":["плывёт, летит, бежит, ползёт","ползёт, летит, плывёт, бежит","плывёт, бежит, летит, ползёт","ползёт, бежит, плывёт, летит","ползёт, летит, бежит, плывёт"],"key":"Б","review":["Как движутся животные","Подберём движение к каждому животному. Черепаха ползёт, ласточка летит, дельфин плывёт, лиса бежит.","Ищем именно такую последовательность действий. Она дана в варианте Б."],"points":1},{"author":"Е. Муравенко","question":"Какой большой _____! Какое название животного <strong>нельзя</strong> вставить вместо прочерка в эту фразу?","choices":["медведь","тюлень","олень","лось","лошадь"],"key":"Д","review":["Название животного","«Какой большой» согласуется со словами мужского рода: медведь, тюлень, олень и лось.","«Лошадь» — слово женского рода. С ним понадобилось бы сказать «Какая большая лошадь!»."],"points":1},{"author":"Е. Муравенко","question":"Какое слово лишнее по смыслу?","choices":["шапка","шарф","берет","кепка","шляпа"],"key":"Б","review":["Предметы одежды","Шапку, берет, кепку и шляпу надевают на голову. Вместе их называют головными уборами.","Шарф обычно повязывают вокруг шеи. Он лишний в этой группе."],"points":1},{"author":"О. Подлесская","question":"Кеша упал с велосипеда, и теперь у него много __________.","choices":["синяк, ссадин и царапин","синяков, ссадинов и царапинов","синякей, ссадин и царапин","синякей, ссадинов и царапинов","синяков, ссадин и царапин"],"key":"Д","review":["Много чего","После слова «много» спрашиваем «чего?». О синяках говорят «много синяков».","У слов «ссадина» и «царапина» во множественном числе здесь формы «ссадин», «царапин». Все три правильные формы собраны в варианте Д."],"points":1},{"author":"Е. Муравенко","question":"Мама ищет одну свою вещь, приговаривая: «Куда же они делись?». Что ищет мама?","choices":["блокнот","кольца","очки","полотенца","расчёску"],"key":"В","review":["Одна вещь и слово «они»","Мама говорит «они делись», то есть использует форму множественного числа. При этом она ищет один предмет.","Очки называют во множественном числе даже тогда, когда это один предмет. Кольца и полотенца во множественном числе обычно означают несколько вещей."],"points":1},{"author":"А. Ковалёва","question":"«Меня зовут Лариса, а это — Зоя, Аня и Ира. А тебя как зовут?» — «А моё имя можно составить из первых букв ваших имён». Как зовут девочку?","choices":["Зина","Лина","Нина","Лиза","Лика"],"key":"Г","review":["Имя из первых букв","Имена Лариса, Зоя, Аня и Ира начинаются с букв Л, З, А и И.","Переставим их в порядке Л, И, З, А. Получаем имя «Лиза»."],"points":1},{"author":"О. Подлесская","question":"Ты меня перегнала, тогда я тебя тоже <em>перегною</em>. Так сказал Антон маме. А как правильно сказать последнее слово?","choices":["перегную","перегню","перегну","перегону","перегоню"],"key":"Д","review":["Форма слова «перегнать»","«Перегнала» — прошедшее время. Антон пытается сказать, что сделает это в будущем, от своего имени.","Правильно «я тебя перегоню». Форма устроена как «я гоню», но с приставкой пере-."],"points":1},{"author":"А. Сомин","question":"Гриша разозлился: _____ газету, _____ тарелку, _____ стул. Как надо заполнить пропуски?","choices":["разбил, сломал, порвал","разбил, порвал, сломал","порвал, сломал, разбил","порвал, разбил, сломал","сломал, порвал, разбил"],"key":"Г","review":["Три вида поломок","Бумажную газету можно порвать, а хрупкую тарелку — разбить.","Про стул говорят «сломал». В предложении получится «порвал газету, разбил тарелку, сломал стул»."],"points":1},{"author":"А. Ковалёва","question":"В сказочном музее обнаружили подмену. Что положили вместо пропавшего волшебного предмета?","choices":["сапоги-скороходы","скатерть-самобранку","шапку-ушанку","ковёр-самолёт","гусли-самогуды"],"key":"В","review":["Сказочный музей","Вспомним необычные свойства сказочных вещей: сапоги ускоряют бег, скатерть накрывает стол, ковёр летает, гусли сами играют.","Шапка-ушанка — обычная тёплая шапка с наушниками. Она выделяется среди волшебных вещей."],"points":1}], {"year":2024,"grade":"1","tasksFile":"1.pdf","answersFile":"1-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2024-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
